import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { resolve, dirname } from 'node:path';
import { interactiveLibrary, interactivePrompt, interactiveTools } from '../src/IM/frontend/src/features/chat/interactive/catalog.js';

const root = resolve(import.meta.dirname, '..');
const schema = JSON.stringify(interactiveLibrary.toJSONSchema(), null, 2);
const outputs = {
  'src/IM/frontend/src/features/chat/interactive/types.ts': `// Generated from product-contracts; do not edit.\n${await readFile(resolve(root, 'packages/product-contracts/src/interactive-types.ts'), 'utf8')}`,
  'packages/product-contracts/src/interactive-catalog.ts': `// Generated by scripts/generate-interactive-ui.ts; edit the frontend catalogue.\nexport const interactiveCatalog = ${schema};\nexport const interactiveTools = ${JSON.stringify(interactiveTools, null, 2)} as const;\n`,
  'packages/dsh-integration/assets/interactive-ui/catalog.json': `${schema}\n`,
  'packages/dsh-integration/assets/interactive-ui/prompt.md': `${interactivePrompt}\n`,
  'packages/personal-assistant/assets/skills/nano-interactive-ui/SKILL.md': `---\nname: nano-interactive-ui\ndescription: Create useful interactive explanations, explorations, comparisons and editors in Web IM.\n---\n\n# Interactive replies\n\nGenerated from the Nano nano-1 catalogue; use the current version unchanged.\n\nCall send_message with target, an independently readable text summary, and interactive: {format: "openui", catalog_version: "nano-1", source: "..."}. Optionally set supersedes_message_id to update your own reply in the same conversation. Use source_mode: "patch" for changed statements; otherwise provide a complete program. Source is at most 64 KiB. Other clients receive the summary. Simple answers need no card.\n\nUsers can explore locally with the complete OpenUI library, request an Agent response through native actions, or ask natural questions. In private chats, available UI state is background captured when the question was sent; decide whether it is relevant, ignore it for new topics, and clarify ambiguous references. Group chats share state only after explicit card actions, never with ordinary text. Repeated exploration and requests are supported. Treat the handwritten text as the current request and the attached fields as data; preserve instructions such as “do not send yet”. A click records a user message, not a completed business action. Execute any actual sending/saving only through the normal tools and authority checks, then report its actual result. Cards are immutable; respond to revisions with a new card. After explicit delivery, end with the exact non-empty final text NO_REPLY. The host suppresses it after the confirmed card. Never end with an empty response.\n\n${interactivePrompt}\n`,
};
for (const [relative, content] of Object.entries(outputs)) {
  const path = resolve(root, relative);
  if (process.argv.includes('--check')) {
    if (await readFile(path, 'utf8') !== content) throw new Error(`Stale generated interactive asset: ${relative}`);
  } else {
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, content);
  }
}
